From 3757347679e4d219bc8225b17314cfabade27879 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:56:39 +0100
Subject: [PATCH] applet: show when a connection was started automatically by
 another one

A VPN set to connect automatically with a network looked just like one
connected by hand, so it wasn't clear why it was on. Its subtitle now
says "Connected automatically with" followed by that network's name.

BUG: 497750
---
 applet/ConnectionItem.qml        |  2 ++
 libs/models/networkmodel.cpp     | 14 ++++++++++++++
 libs/models/networkmodel.h       |  1 +
 libs/models/networkmodelitem.cpp | 13 +++++++++++++
 libs/models/networkmodelitem.h   |  4 ++++
 5 files changed, 34 insertions(+)

diff --git a/applet/ConnectionItem.qml b/applet/ConnectionItem.qml
index e2a79fd2f..5a8f53c55 100644
--- a/applet/ConnectionItem.qml
+++ b/applet/ConnectionItem.qml
@@ -313,6 +313,8 @@ PlasmaExtras.ExpandableListItem {
             }
         } else if (model.Uuid && model.ConnectionState === PlasmaNM.Enums.Deactivated) {
             return model.LastUsed
+        } else if (model.ConnectionState === PlasmaNM.Enums.Activated && model.BaseConnection) {
+            return i18nc("@info:status %1 is the name of the connection that started this one", "Connected automatically with %1", model.BaseConnection)
         } else if (model.ConnectionState === PlasmaNM.Enums.Activated && showSpeed) {
             return i18nc("Download and upload rates in some unit per second", "↓ %1/s, ↑ %2/s",
                 KCoreAddons.Format.formatByteSize(rxSpeed),
diff --git a/libs/models/networkmodel.cpp b/libs/models/networkmodel.cpp
index 0aec0317b..f1dd411f9 100644
--- a/libs/models/networkmodel.cpp
+++ b/libs/models/networkmodel.cpp
@@ -94,6 +94,8 @@ QVariant NetworkModel::data(const QModelIndex &index, int role) const
             return item->rxBytes();
         case TxBytesRole:
             return item->txBytes();
+        case BaseConnectionRole:
+            return item->baseConnection();
         case DelayModelUpdatesRole:
             return item->delayModelUpdates();
         case Qt::AccessibleDescriptionRole:
@@ -159,6 +161,7 @@ QHash<int, QByteArray> NetworkModel::roleNames() const
     roles[VpnType] = "VpnType";
     roles[RxBytesRole] = "RxBytes";
     roles[TxBytesRole] = "TxBytes";
+    roles[BaseConnectionRole] = "BaseConnection";
     roles[DelayModelUpdatesRole] = "DelayModelUpdates";

     return roles;
@@ -356,6 +359,15 @@ void NetworkModel::addActiveConnection(const NetworkManager::ActiveConnection::P
         return;
     }

+    // Find the connection that activated this one as one of its secondary connections
+    QString baseConnection;
+    for (const NetworkManager::ActiveConnection::Ptr &other : NetworkManager::activeConnections()) {
+        if (other->path() != activeConnection->path() && other->connection() && other->connection()->settings()->secondaries().contains(settings->uuid())) {
+            baseConnection = other->id();
+            break;
+        }
+    }
+
     // Not necessary to have device for VPN connections
     if (activeConnection && !activeConnection->vpn() && !activeConnection->devices().isEmpty()) {
         device = NetworkManager::findNetworkInterface(activeConnection->devices().first());
@@ -371,6 +383,7 @@ void NetworkModel::addActiveConnection(const NetworkManager::ActiveConnection::P
         if (((device && device->uni() == item->devicePath()) || item->devicePath().isEmpty()) || item->type() == NetworkManager::ConnectionSettings::Vpn) {
             item->setActiveConnectionPath(activeConnection->path());
             item->setConnectionState(activeConnection->state());
+            item->setBaseConnection(baseConnection);
             if (activeConnection->vpn()) {
                 NetworkManager::VpnConnection::Ptr vpnConnection = activeConnection.objectCast<NetworkManager::VpnConnection>();
                 NetworkManager::VpnConnection::State state = vpnConnection->state();
@@ -776,6 +789,7 @@ void NetworkModel::activeConnectionRemoved(const QString &activeConnection)
         item->setTimestamp(disconnectTime);
         item->setActiveConnectionPath(QString());
         item->setConnectionState(NetworkManager::ActiveConnection::Deactivated);
+        item->setBaseConnection(QString());
         item->setVpnState(NetworkManager::VpnConnection::Disconnected);
         updateItem(item);
         qCDebug(PLASMA_NM_LIBS_LOG).nospace() << "Item " << item->name() << ": active connection removed";
diff --git a/libs/models/networkmodel.h b/libs/models/networkmodel.h
index 171cca36f..ad0d7e322 100644
--- a/libs/models/networkmodel.h
+++ b/libs/models/networkmodel.h
@@ -64,6 +64,7 @@ public:
         VpnType,
         RxBytesRole,
         TxBytesRole,
+        BaseConnectionRole,
         // writable roles
         DelayModelUpdatesRole,
     };
diff --git a/libs/models/networkmodelitem.cpp b/libs/models/networkmodelitem.cpp
index 70d48fb6a..0e6bc2774 100644
--- a/libs/models/networkmodelitem.cpp
+++ b/libs/models/networkmodelitem.cpp
@@ -96,6 +96,19 @@ void NetworkModelItem::setActiveConnectionPath(const QString &path)
     m_activeConnectionPath = path;
 }

+QString NetworkModelItem::baseConnection() const
+{
+    return m_baseConnection;
+}
+
+void NetworkModelItem::setBaseConnection(const QString &name)
+{
+    if (m_baseConnection != name) {
+        m_baseConnection = name;
+        m_changedRoles << NetworkModel::BaseConnectionRole;
+    }
+}
+
 QString NetworkModelItem::connectionPath() const
 {
     return m_connectionPath;
diff --git a/libs/models/networkmodelitem.h b/libs/models/networkmodelitem.h
index a61cb0e03..6abbc0483 100644
--- a/libs/models/networkmodelitem.h
+++ b/libs/models/networkmodelitem.h
@@ -52,6 +52,9 @@ public:
     QString activeConnectionPath() const;
     void setActiveConnectionPath(const QString &path);

+    QString baseConnection() const;
+    void setBaseConnection(const QString &name);
+
     QString connectionPath() const;
     void setConnectionPath(const QString &path);

@@ -153,6 +156,7 @@ private:
     QString computeIcon() const;
     void refreshIcon();
     QString m_activeConnectionPath;
+    QString m_baseConnection;
     QString m_connectionPath;
     NetworkManager::ActiveConnection::State m_connectionState;
     QString m_devicePath;
-- 
